// Frozen scores: first maximum has the same stable tie order as stable_sort.
inline size_t firstStableMaximum(const std::vector<ScoredMove>& scored){
 if(scored.empty())return 0;
 return size_t(std::max_element(scored.begin(),scored.end(),[](const ScoredMove& a,const ScoredMove& b){return a.score<b.score;})-scored.begin());
}
inline Move nextStableOrdered(std::vector<ScoredMove>& scored,size_t visit,size_t first,bool deferred){
 if(deferred&&visit==1)std::stable_sort(scored.begin(),scored.end(),[](const ScoredMove& a,const ScoredMove& b){return a.score>b.score;});
 return scored[visit==0?first:visit].move;
}

